132	    static String getCodeFromTermcap(String termcap, boolean cursorKeysApplication, boolean keypadApplication) {
133	        Integer keyCodeAndMod = TERMCAP_TO_KEYCODE.get(termcap);
134	        if (keyCodeAndMod == null) return null;
135	        int keyCode = keyCodeAndMod;
136	        int keyMod = 0;
137	        if ((keyCode & KEYMOD_SHIFT) != 0) {
138	            keyMod |= KEYMOD_SHIFT;
139	            keyCode &= ~KEYMOD_SHIFT;
140	        }
141	        if ((keyCode & KEYMOD_CTRL) != 0) {
142	            keyMod |= KEYMOD_CTRL;
143	            keyCode &= ~KEYMOD_CTRL;
144	        }
145	        if ((keyCode & KEYMOD_ALT) != 0) {
146	            keyMod |= KEYMOD_ALT;
147	            keyCode &= ~KEYMOD_ALT;
148	        }
149	        if ((keyCode & KEYMOD_NUM_LOCK) != 0) {
150	            keyMod |= KEYMOD_NUM_LOCK;
151	            keyCode &= ~KEYMOD_NUM_LOCK;
152	        }
153	        return getCode(keyCode, keyMod, cursorKeysApplication, keypadApplication);
154	    }
