156	    public static String getCode(int keyCode, int keyMode, boolean cursorApp, boolean keypadApplication) {
157	        boolean numLockOn = (keyMode & KEYMOD_NUM_LOCK) != 0;
158	        keyMode &= ~KEYMOD_NUM_LOCK;
159	        switch (keyCode) {
160	            case KEYCODE_DPAD_CENTER:
161	                return "\015";
162	
163	            case KEYCODE_DPAD_UP:
164	                return (keyMode == 0) ? (cursorApp ? "\033OA" : "\033[A") : transformForModifiers("\033[1", keyMode, 'A');
165	            case KEYCODE_DPAD_DOWN:
166	                return (keyMode == 0) ? (cursorApp ? "\033OB" : "\033[B") : transformForModifiers("\033[1", keyMode, 'B');
167	            case KEYCODE_DPAD_RIGHT:
168	                return (keyMode == 0) ? (cursorApp ? "\033OC" : "\033[C") : transformForModifiers("\033[1", keyMode, 'C');
169	            case KEYCODE_DPAD_LEFT:
170	                return (keyMode == 0) ? (cursorApp ? "\033OD" : "\033[D") : transformForModifiers("\033[1", keyMode, 'D');
171	
172	            case KEYCODE_MOVE_HOME:
173	                // Note that KEYCODE_HOME is handled by the system and never delivered to applications.
174	                // On a Logitech k810 keyboard KEYCODE_MOVE_HOME is sent by FN+LeftArrow.
175	                return (keyMode == 0) ? (cursorApp ? "\033OH" : "\033[H") : transformForModifiers("\033[1", keyMode, 'H');
176	            case KEYCODE_MOVE_END:
177	                return (keyMode == 0) ? (cursorApp ? "\033OF" : "\033[F") : transformForModifiers("\033[1", keyMode, 'F');
