179	            // An xterm can send function keys F1 to F4 in two modes: vt100 compatible or
180	            // not. Because Vim may not know what the xterm is sending, both types of keys
181	            // are recognized. The same happens for the <Home> and <End> keys.
182	            // normal vt100 ~
183	            // <F1> t_k1 <Esc>[11~ <xF1> <Esc>OP *<xF1>-xterm*
184	            // <F2> t_k2 <Esc>[12~ <xF2> <Esc>OQ *<xF2>-xterm*
185	            // <F3> t_k3 <Esc>[13~ <xF3> <Esc>OR *<xF3>-xterm*
186	            // <F4> t_k4 <Esc>[14~ <xF4> <Esc>OS *<xF4>-xterm*
187	            // <Home> t_kh <Esc>[7~ <xHome> <Esc>OH *<xHome>-xterm*
188	            // <End> t_@7 <Esc>[4~ <xEnd> <Esc>OF *<xEnd>-xterm*
189	            case KEYCODE_F1:
190	                return (keyMode == 0) ? "\033OP" : transformForModifiers("\033[1", keyMode, 'P');
191	            case KEYCODE_F2:
192	                return (keyMode == 0) ? "\033OQ" : transformForModifiers("\033[1", keyMode, 'Q');
193	            case KEYCODE_F3:
194	                return (keyMode == 0) ? "\033OR" : transformForModifiers("\033[1", keyMode, 'R');
195	            case KEYCODE_F4:
196	                return (keyMode == 0) ? "\033OS" : transformForModifiers("\033[1", keyMode, 'S');
197	            case KEYCODE_F5:
198	                return transformForModifiers("\033[15", keyMode, '~');
199	            case KEYCODE_F6:
200	                return transformForModifiers("\033[17", keyMode, '~');
201	            case KEYCODE_F7:
202	                return transformForModifiers("\033[18", keyMode, '~');
203	            case KEYCODE_F8:
204	                return transformForModifiers("\033[19", keyMode, '~');
205	            case KEYCODE_F9:
206	                return transformForModifiers("\033[20", keyMode, '~');
207	            case KEYCODE_F10:
208	                return transformForModifiers("\033[21", keyMode, '~');
209	            case KEYCODE_F11:
210	                return transformForModifiers("\033[23", keyMode, '~');
211	            case KEYCODE_F12:
212	                return transformForModifiers("\033[24", keyMode, '~');
213	
214	            case KEYCODE_SYSRQ:
215	                return "\033[32~"; // Sys Request / Print
216	            // Is this Scroll lock? case Cancel: return "\033[33~";
217	            case KEYCODE_BREAK:
218	                return "\033[34~"; // Pause/Break
219	
220	            case KEYCODE_ESCAPE:
221	            case KEYCODE_BACK:
222	                return "\033";
223	
224	            case KEYCODE_INSERT:
225	                return transformForModifiers("\033[2", keyMode, '~');
226	            case KEYCODE_FORWARD_DEL:
227	                return transformForModifiers("\033[3", keyMode, '~');
228	
229	            case KEYCODE_PAGE_UP:
230	                return transformForModifiers("\033[5", keyMode, '~');
231	            case KEYCODE_PAGE_DOWN:
232	                return transformForModifiers("\033[6", keyMode, '~');
233	            case KEYCODE_DEL:
234	                String prefix = ((keyMode & KEYMOD_ALT) == 0) ? "" : "\033";
235	                // Just do what xterm and gnome-terminal does:
236	                return prefix + (((keyMode & KEYMOD_CTRL) == 0) ? "\u007F" : "\u0008");
237	            case KEYCODE_NUM_LOCK:
238	                if (keypadApplication) {
239	                    return "\033OP";
240	                } else {
241	                    return null;
242	                }
